use core.process as process

struct Command {
    operation: String
    name: String
    format: String
    dry_run: Bool
}

fn run() {
    args :: process.argv()
    raw_operation :: args.get(1) ?? panic("missing command")
    operation := ""
    if raw_operation == "list" || raw_operation == "ls" {
        operation = "list"
    } else if raw_operation == "inspect" {
        operation = "inspect"
    } else if raw_operation == "remove" || raw_operation == "rm" {
        operation = "remove"
    } else {
        panic("unknown command {raw_operation}")
    }

    name := ""
    format := "text"
    dry_run := false
    i := 2
    loop i < args.len() {
        argument :: args.get(i) ?? panic("missing argument")
        if argument == "--json" {
            format = "json"
        } else if argument == "--format" {
            i += 1
            format_value :: args.get(i) ?? panic("missing value for --format")
            if format_value != "text" && format_value != "json" -> panic("invalid format {format_value}")
            format = format_value
        } else if argument == "--dry-run" {
            dry_run = true
        } else {
            if !name.is_empty() -> panic("multiple names")
            name = argument
        }
        i += 1
    }
    if name.is_empty() -> panic("missing name")

    command :: Command{operation: operation, name: name, format: format, dry_run: dry_run}
    dry_text :: if command.dry_run -> "true" else -> "false"
    print("{command.operation} name={command.name} format={command.format} dry_run={dry_text}")
}
